// Wheel realism index — record JAH-GPC-RACINGWHEEL-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"torque_nm": 4, "rotation_deg": 900, "price_usd": 300};
var value = (m.torque_nm*m.rotation_deg/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-RACINGWHEEL-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-RACINGWHEEL-000001|' + value.toFixed(2) + ' realism index');

